mapper.select:
select r.*,
       d.device_name as deviceName,
       d.device_code as deviceCode,
       d.status as deviceStatus,
       l.lab_name as labName,
       u.real_name as applicantName,
       h.real_name as handlerName
from lab_device_repair r
join lab_device d on d.id = r.device_id and d.deleted = 0
join lab l on l.id = r.lab_id and l.deleted = 0
left join sys_user u on u.id = r.applicant_user_id
left join sys_user h on h.id = r.handler_user_id
where l.department_id = #{departmentId}

    and r.lab_id = #{labId}


    and l.lab_type = #{labType}


    and r.device_id = #{deviceId}


    and r.status = #{status}


    and r.applicant_user_id = #{applicantUserId}

order by r.id desc
limit #{offset}, #{pageSize}

select count(*)
from lab_device_repair r
join lab_device d on d.id = r.device_id and d.deleted = 0
join lab l on l.id = r.lab_id and l.deleted = 0
where l.department_id = #{departmentId}

    and r.lab_id = #{labId}


    and l.lab_type = #{labType}


    and r.device_id = #{deviceId}


    and r.status = #{status}


    and r.applicant_user_id = #{applicantUserId}

select count(*)
from lab_device_repair
where device_id = #{deviceId}
  and status in (1, 2)

    and id != #{excludeId}

mapper.update:
update lab_device_repair
set status = #{status},
    handler_user_id = #{handlerUserId},
    handling_result = #{handlingResult},
    handled_at = #{handledAt}
where id = #{id}
